create schema if not exists aau_research_v23;
create table if not exists aau_research_v23.runs(run_id uuid primary key,benchmark_hash text not null,seq integer not null default 0,next_phase text,status text not null default 'running',state jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists aau_research_v23.events(run_id uuid not null references aau_research_v23.runs(run_id),seq integer not null,phase text not null,details jsonb not null,recorded_at timestamptz not null default now(),primary key(run_id,seq));
create table if not exists aau_research_v23.outbox(id bigint generated always as identity primary key,run_id uuid not null references aau_research_v23.runs(run_id),seq integer not null,published_at timestamptz,unique(run_id,seq));
create index if not exists v23_outbox_pending on aau_research_v23.outbox(published_at,id);
alter table aau_research_v23.runs enable row level security;
alter table aau_research_v23.events enable row level security;
alter table aau_research_v23.outbox enable row level security;
create table if not exists aau_research_v23.calls(run_id uuid not null references aau_research_v23.runs(run_id),phase text not null,attempt integer not null,model_request_hash text not null,status text not null default 'sent_or_uncertain',provider_tokens integer,finish_reason text,response_hash text,created_at timestamptz not null default now(),primary key(run_id,phase,attempt));
alter table aau_research_v23.calls enable row level security;
